DROP TABLE IF EXISTS cma_sqlite_books;
CREATE TABLE cma_sqlite_books(id INTEGER PRIMARY KEY,title TEXT NOT NULL,pages INTEGER);
INSERT INTO cma_sqlite_books(title,pages) VALUES('Moon Trip',60);
SELECT id,title,pages FROM cma_sqlite_books;

DROP TABLE IF EXISTS cma_sqlite_scores;
CREATE TABLE cma_sqlite_scores(points INTEGER NOT NULL CHECK(points>=0));
INSERT INTO cma_sqlite_scores VALUES(5);
SELECT points FROM cma_sqlite_scores;

PRAGMA foreign_keys=ON;
DROP TABLE IF EXISTS cma_sqlite_loans;
DROP TABLE IF EXISTS cma_sqlite_readers;
CREATE TABLE cma_sqlite_readers(id INTEGER PRIMARY KEY);
CREATE TABLE cma_sqlite_loans(reader_id INTEGER REFERENCES cma_sqlite_readers(id));
INSERT INTO cma_sqlite_readers VALUES(1);
INSERT INTO cma_sqlite_loans VALUES(1);
SELECT reader_id FROM cma_sqlite_loans;

DROP TABLE IF EXISTS cma_sqlite_points;
CREATE TABLE cma_sqlite_points(points INTEGER);
BEGIN;
INSERT INTO cma_sqlite_points VALUES(7);
